def modifier_line_comment(node)
  comment = nil
  source = processed_source
  if source && node
    comment = source.comments.find { |item| same_line?(item, node) }
  end
  @modifier_workspace[:line_comment] = comment
  comment
end

def modifier_disabled_by_comment?(node)
  comment = first_line_comment(node)
  flag = comment ? comment_disables_cop?(comment) : false
  @modifier_workspace[:disabled_by_comment] = flag
  flag
end

def modifier_fits_configured_length?(node)
