  count
end

def modifier_body_commented?(node)
  flag = false
  body = node.body if node.respond_to?(:body)
  if body && body.respond_to?(:source_range)
    flag = processed_source.contains_comment?(body.source_range)
  end
  @modifier_workspace[:body_commented] = flag
  flag
end

def modifier_condition_assigns?(node)
  flag = false
  condition = node.condition if node.respond_to?(:condition)
  if condition && condition.respond_to?(:each_node)
    flag = condition.each_node.any?(&:lvasgn_type?)
  end
  @modifier_workspace[:condition_assigns] = flag
  flag
end

