def assignment_should_be_skipped?(asgn_node)
  skipped = (asgn_node.call_type? && !asgn_node.assignment_method?) ||
            empty_condition?(asgn_node) ||
            (safe_assignment_allowed? && safe_assignment?(asgn_node))
  @assignment_workspace[:skipped] = skipped
  skipped
end

def allowed_assignment_construct?(asgn_node)
